"""Distinguish cumulative buff state and skip/recovery order."""
import json
from lupa.lua53 import LuaRuntime
from reconcile_generator_logic import ROOT,OUT
from verify_generator_timer_rules import SETUP as TIMER_SETUP
CASES={
 'earlier_buff_remains_active':"local m=setmetatable({m_buffConfig={{buffType='moreLuckyProduce'},{buffType='extraLuckyProduce'}}},GeneratorBoostActivityModel);m.GetState=function() return 1 end;m.GetBuffLevel=function() return 2 end;assert(m:IsBuffActive('moreLuckyProduce') and m:IsBuffActive('extraLuckyProduce'))",
 'table_priority_with_both_active':"local a={};local b={};GM.ConfigModel={GetLocalConfig=function() return {MoreLuckyProduce=a,ExtraLuckyProduce=b} end};local m=setmetatable({m_buffConfig={{buffType='moreLuckyProduce'},{buffType='extraLuckyProduce'}}},GeneratorBoostActivityModel);m.GetState=function() return 1 end;m.GetBuffLevel=function() return 2 end;assert(m:GetLuckyProduceConfig()==a and m:GetItemModelConfig()==a)",
 'ended_disables_accumulated_buff':"local m=setmetatable({m_buffConfig={{buffType='nocd'}}},GeneratorBoostActivityModel);m.GetState=function() return 2 end;m.GetBuffLevel=function() return 1 end;assert(m:IsBuffActive('nocd')==false)",
 'zero_level_clear_is_noop':"local m=setmetatable({},GeneratorBoostActivityModel);m.GetBuffLevel=function() return 0 end;m:ClearBuff()",
 'clear_order_before_config_restore':"local seq={};local m=setmetatable({m_dbTable={Remove=function(_,k) seq[#seq+1]=k end}},GeneratorBoostActivityModel);m.GetBuffLevel=function() return 1 end;m.RemoveExtraProduceCache=function() seq[#seq+1]='cache' end;m.RemoveExtraLuckyProduceCache=function() seq[#seq+1]='luckycache' end;m.ReloadItemModelConfig=function() seq[#seq+1]='itemconfig' end;m.ReloadLuckyProduceConfig=function() seq[#seq+1]='luckyconfig' end;m.SetActiveSpread=function(_,v) assert(v==false);seq[#seq+1]='inactive' end;EventDispatcher.DispatchEvent=function() seq[#seq+1]='event' end;m:ClearBuff();assert(table.concat(seq,',')=='ActiveBuffLevel,ExtraProduceTotalSpreadCount,ExtraProduceLeftSpreadCount,cache,luckycache,itemconfig,luckyconfig,inactive,event')",
 'buff_skip_can_leave_storage_timer':"GM.AudioModel={PlayEffect=function() end};AudioFileConfigName={};local m=model{m_state=3,m_startTimer=900,m_itemRestNumber=0,m_itemMaxNumber=80,m_storageRestNumber=10,m_storageMaxNumber=240,m_itemRecoveryDuration=30,m_storageRecoveryDuration=60};m.m_itemModel.GetBoardModel=function() return {IgnoreBI=true,SaveItemProperty=function() saves=saves+1 end} end;m:OnTimeSkip(nil,1);assert(m.m_itemRestNumber==80 and m.m_storageRestNumber==0 and m.m_startTimer==1000)",
 'buff_with_rest_does_not_skip':"local m=model{m_itemRestNumber=1};m.CanSupportCDBuff=function() return true end;m.OnTimeSkip=function() error('unexpected skip') end;m:TryUseCDBuff();assert(notices==1)",
 'no_qualified_buff_no_notice':"local m=model{m_itemRestNumber=0};m.CanSupportCDBuff=function() return false end;m.CanSupportGeneratorBoostCDBuff=function() return false end;m.CanTestSupportCDFree=function() return false end;m:TryUseCDBuff();assert(notices==0)",
 'clear_state_order_and_progress_reset':"local seq={};local m=setmetatable({m_curProgress={9},m_lastShowProgress={8}},GeneratorBoostActivityModel);m.SetCurProgress=function(self) assert(self.m_curProgress[1]==0 and self.m_curProgress[4]==0);seq[#seq+1]='current' end;m.SetLastShowProgress=function(self) assert(self.m_curProgress[1]==0);seq[#seq+1]='last' end;m.ClearBuff=function() seq[#seq+1]='buff' end;m:ClearState();assert(table.concat(seq,',')=='current,last,buff')",
 'round_increment_persists_and_logs':"local saved;local m=setmetatable({m_dbTable={Set=function(_,k,_,v) saved={k,v} end},m_activityDefinition={BIStartRound='round'}} ,GeneratorBoostActivityModel);m.GetRoundNum=function() return 4 end;m.GetServerConfigGroupId=function() return 7 end;GM.BIManager={LogAction=function(_,kind,x) assert(kind=='round' and x.r==4 and x.g==7) end};m:AddRoundNum();assert(saved[2]==5)",
 'progress_add_caps_and_persists':"local writes=0;local m=setmetatable({m_taskConfig={{index=1,taskType=7,num=5}},m_curProgress={3},m_activityDefinition={BIFinishTask='finish',TaskFinishedEvent=3}},GeneratorBoostActivityModel);m.GetFinishedTaskCount=function() return 0 end;m.GetRoundNum=function() return 1 end;m.GetServerConfigGroupId=function() return 2 end;m.SetCurProgress=function() writes=writes+1 end;GM.BIManager={LogAction=function() end};EventDispatcher.DispatchEvent=function() end;m:_OnProgressGain({operation=TaskEventProgressGainModule.TaskOper.Add,type=7,num=9});assert(m.m_curProgress[1]==5 and writes==1)",
 'progress_non_add_is_ignored':"local m=setmetatable({m_taskConfig={{index=1,taskType=7,num=5}},m_curProgress={3}},GeneratorBoostActivityModel);m:_OnProgressGain({operation=TaskEventProgressGainModule.TaskOper.Update,type=7,num=9});assert(m.m_curProgress[1]==3)",
 'second_completed_task_levels_buff':"local leveled=0;local m=setmetatable({m_taskConfig={{index=1,taskType=7,num=2}},m_curProgress={1},m_activityDefinition={BIFinishTask='finish',TaskFinishedEvent=3}},GeneratorBoostActivityModel);m.GetFinishedTaskCount=function() return 1 end;m.GetRoundNum=function() return 1 end;m.GetServerConfigGroupId=function() return 2 end;m.SetCurProgress=function() end;m.BuffLevelUp=function() leveled=leveled+1 end;GM.BIManager={LogAction=function() end};EventDispatcher.DispatchEvent=function() end;m:_OnProgressGain({operation=TaskEventProgressGainModule.TaskOper.Add,type=7,num=1});assert(leveled==1 and m.m_curProgress[1]==2)",
}
def main():
 modules=json.loads((ROOT/'analysis_data/logic_index/lua_modules.json').read_text(encoding='utf-8'));rows=[]
 for mode in ('bytecode','recovered-source'):
  for name,body in CASES.items():
   try:
    lua=LuaRuntime();lua.execute(TIMER_SETUP+"\nActivityState={Started=1};LocalConfigKey={};EEventType.GeneratorBoostBuffCleared=2;TaskEventProgressGainModule={TaskOper={Add=1,Update=2}};TaskEventType={OrderFinish=99}")
    for h in ('1b00d962a168ea07b90fa80134c8c7cbc16220a14cacc30e427aa8467d832174','e153e5646c658a0cfbd2c7ca4bce3a07202bab1ef4e5ef0782585dca7f5e7f01'):
     m=next(m for m in modules if m['sha256']==h);p=ROOT/m['standard_path'] if mode=='bytecode' else ROOT/'analysis_data/logic_index/lua/decoded'/h/'decompiled.lua';lua.execute(p.read_bytes() if mode=='bytecode' else p.read_text(encoding='utf-8'))
    lua.execute(body);rows.append(dict(case=name,mode=mode,status='passed'))
   except Exception as e:rows.append(dict(case=name,mode=mode,status='failed',error=str(e)))
 result={'cases':rows,'passed':sum(r['status']=='passed' for r in rows),'total':len(rows),'limits':'Selected direct lifecycle contracts, controlled model eligibility, clock, DB and dispatch dependencies; not full listener or runtime verification.'}
 (OUT/'buff_lifecycle_tests.json').write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf-8');print(json.dumps(result,ensure_ascii=False));assert result['passed']==result['total']
if __name__=='__main__':main()
